package br.com.erp;
import java.util.*;
import java.math.BigDecimal;
import java.time.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class CoreFlowGuardTest extends SaleFixture {
 String classify(String code,String quantity,LocalDate expiry)throws Exception{return postApi("/api/v1/inventory/lots/classify",auth,Map.of("requestId",UUID.randomUUID(),"warehouseId",warehouse,"productId",product,"code",code,"expiresOn",expiry,"quantity",quantity),200).get("lotId").asText();}
 BigDecimal lot(String id){return db.queryForObject("SELECT quantity FROM stock_lot_balance WHERE tenant_id=? AND lot_id=? AND warehouse_id=?",BigDecimal.class,tenant,UUID.fromString(id),UUID.fromString(warehouse));}
 @Test void expiredLotsCannotBeSoldAndRollbackIncludesCashAndStock()throws Exception{String lot=classify("EXPIRED","10",LocalDate.now(ZoneId.of("America/Sao_Paulo")).minusDays(1));sell(input(UUID.randomUUID(),"1","10.25","20"),409);assertEquals(0,balance().signum());assertEquals(0,new BigDecimal("10").compareTo(quantity(product)));assertEquals(0,new BigDecimal("10").compareTo(lot(lot)));assertEquals(0,count("pos_sale"));assertEquals(0,count("sale_commercial"));}
 @Test void fefoAndSaleCancellationRestoreOriginalAllocations()throws Exception{var today=LocalDate.now(ZoneId.of("America/Sao_Paulo"));String near=classify("NEAR","3",today.plusDays(1)),far=classify("FAR","2",today.plusDays(5));var sale=sell(input(UUID.randomUUID(),"4","10.25","50"),201);assertEquals(0,lot(near).signum());assertEquals(0,BigDecimal.ONE.compareTo(lot(far)));postApi("/api/v1/pos/sales/"+sale.get("id").asText()+"/cancel",auth,Map.of("requestId",UUID.randomUUID(),"version",0,"note","Cancelamento conferido","externalRefundsConfirmed",false),200);assertEquals(0,new BigDecimal("3").compareTo(lot(near)));assertEquals(0,new BigDecimal("2").compareTo(lot(far)));assertEquals(0,balance().signum());}
 @Test void branchPriceAndPromotionAreRecheckedAndSnapshotsRemainHistorical()throws Exception{http.perform(put("/api/v1/branch-prices").header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(Map.of("requestId",UUID.randomUUID(),"branchId",branch,"productId",product,"version",0,"price","20","note","Preço da filial conferido")))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());http.perform(put("/api/v1/commercial/promotions").header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(Map.of("requestId",UUID.randomUUID(),"branchId",branch,"productId",product,"version",0,"percent","10","startsOn",LocalDate.now().minusDays(1),"endsOn",LocalDate.now().plusDays(1),"active",true)))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());sell(input(UUID.randomUUID(),"1","10.25","30"),409);var sale=sell(input(UUID.randomUUID(),"1","18.00","30"),201);money("18.00",sale.get("total"));db.update("UPDATE branch_price SET price=40 WHERE tenant_id=?",tenant);money("18.00",getApi("/api/v1/pos/sales/"+sale.get("id").asText(),auth,200).get("items").get(0).get("unitPrice"));}
}
